CREATE TABLE IF NOT EXISTS course_group_topic_releases (course_group INTEGER NOT NULL REFERENCES course_groups(id), topic INTEGER NOT NULL REFERENCES topics(id), active INTEGER NOT NULL CHECK(active IN (0,1)), PRIMARY KEY(course_group,topic));
CREATE TABLE IF NOT EXISTS course_group_task_releases (course_group INTEGER NOT NULL REFERENCES course_groups(id), task INTEGER NOT NULL REFERENCES tasks(id), active INTEGER NOT NULL CHECK(active IN (0,1)), PRIMARY KEY(course_group,task));
CREATE TABLE IF NOT EXISTS course_group_flexible_topic_releases (course_group INTEGER NOT NULL REFERENCES course_groups(id), flexible_topic INTEGER NOT NULL REFERENCES flexible_topics(id), active INTEGER NOT NULL CHECK(active IN (0,1)), PRIMARY KEY(course_group,flexible_topic));
CREATE TABLE IF NOT EXISTS course_group_flexible_task_releases (course_group INTEGER NOT NULL REFERENCES course_groups(id), flexible_task INTEGER NOT NULL REFERENCES flexible_tasks(id), active INTEGER NOT NULL CHECK(active IN (0,1)), PRIMARY KEY(course_group,flexible_task));
